@import "tailwindcss";
@import "@heroui/styles";
@import "../design/component-theme.css";
@import "../design/layout.css";

:root {
  color: var(--dh-text);
  background: var(--dh-background);
  font-family:
    "Hiragino Sans",
    "Hiragino Kaku Gothic ProN",
    "Yu Gothic UI",
    "Yu Gothic",
    system-ui,
    sans-serif;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--dh-background);
  color: var(--dh-text);
  font-size: var(--dh-type-body);
  line-height: var(--dh-type-line-height-body);
}

a {
  color: inherit;
}

.app-header {
  border-bottom: 1px solid var(--dh-border);
  background: color-mix(in oklch, var(--dh-surface) 92%, var(--dh-accent-soft));
}

.app-header__inner {
  padding-block: var(--dh-space-4);
}

.app-header__eyebrow {
  margin: 0 0 var(--dh-space-1);
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.back-link {
  width: fit-content;
}

.detail-actions {
  display: flex;
  gap: var(--dh-space-2);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.drawer-description {
  margin: 0;
  color: var(--dh-text-muted);
}

.detail-list {
  margin: 0;
  display: grid;
  gap: var(--dh-space-4);
}

.detail-row {
  display: grid;
  gap: var(--dh-space-1);
}

.detail-row dt {
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.detail-row dd {
  margin: 0;
  white-space: pre-wrap;
}

.empty-state {
  background: var(--dh-surface);
}

.alert-dialog__body {
  display: grid;
  gap: var(--dh-space-4);
}

@media (max-width: 767px) {
  .detail-actions {
    width: 100%;
    flex-direction: column;
  }

  .detail-actions .button {
    width: 100%;
  }
}

import {
  Alert,
  AlertDialog,
  Button,
  Card,
  Chip,
  Description,
  Drawer,
  FieldError,
  Form,
  Input,
  Label,
  Link,
  ListBox,
  SearchField,
  Select,
  Table,
  TextField,
  Toast,
  toast,
} from "@heroui/react";
import { useEffect, useId, useState } from "react";
import { HashRouter, Navigate, Route, Routes, useLocation, useNavigate, useParams } from "react-router-dom";
import {
  type CustomerDetail,
  type CustomerStatus,
  type CustomerSummary,
  deleteCustomer,
  getCustomerDetail,
  listCustomerSummaries,
  updateCustomer,
} from "./fixtures";

const DETAIL_DELAY_MS = 120;
const LIST_DELAY_MS = 120;

const STATUS_OPTIONS: Array<{ id: CustomerStatus; label: CustomerStatus }> = [
  { id: "商談中", label: "商談中" },
  { id: "利用中", label: "利用中" },
  { id: "休眠", label: "休眠" },
];

const DETAIL_STATE_NAMES = new Set([
  "default",
  "drawer-open",
  "invalid-email",
  "loading",
  "success",
  "failure",
  "delete-confirm",
] as const);

type DetailDemoState =
  | "default"
  | "drawer-open"
  | "invalid-email"
  | "loading"
  | "success"
  | "failure"
  | "delete-confirm";

type EditableCustomerFields = Pick<
  CustomerDetail,
  "companyName" | "contactName" | "email" | "status"
>;

type FormErrors = Partial<Record<keyof EditableCustomerFields, string>>;
type FeedbackTone = "success" | "danger";

function getCompanyHref(customerId: string, state?: string) {
  return state ? `#/customers/${customerId}?state=${state}` : `#/customers/${customerId}`;
}

function getListHref(state?: string) {
  return state ? `#/customers?state=${state}` : "#/customers";
}

function getStatusVariant(status: CustomerStatus) {
  if (status === "利用中") return "secondary";
  if (status === "商談中") return "primary";
  return "tertiary";
}

function isEmailValid(email: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function toDraft(customer: CustomerDetail): EditableCustomerFields {
  return {
    companyName: customer.companyName,
    contactName: customer.contactName,
    email: customer.email,
    status: customer.status,
  };
}

function toDemoDraft(customer: CustomerDetail): EditableCustomerFields {
  return {
    companyName: `${customer.companyName} CS支援`,
    contactName: `${customer.contactName} 担当`,
    email: "team-success@example.com",
    status: "商談中",
  };
}

function getDetailState(rawState: string | null): DetailDemoState {
  if (rawState && DETAIL_STATE_NAMES.has(rawState as DetailDemoState)) {
    return rawState as DetailDemoState;
  }
  return "default";
}

function AppHeader() {
  return (
    <header className="app-header">
      <div className="page-shell app-header__inner">
        <div>
          <p className="app-header__eyebrow">営業・CS</p>
          <strong>顧客管理</strong>
        </div>
      </div>
    </header>
  );
}

function PageFeedback({
  title,
  description,
  tone = "success",
}: {
  title: string;
  description: string;
  tone?: FeedbackTone;
}) {
  return (
    <Alert.Root status={tone}>
      <Alert.Content>
        <Alert.Title>{title}</Alert.Title>
        <Alert.Description>{description}</Alert.Description>
      </Alert.Content>
    </Alert.Root>
  );
}

function EmptyState({ title, description }: { title: string; description: string }) {
  return (
    <Card.Root className="empty-state">
      <Card.Header>
        <Card.Title>{title}</Card.Title>
        <Card.Description>{description}</Card.Description>
      </Card.Header>
    </Card.Root>
  );
}

function CustomerSummaryTable({
  items,
  detailState,
}: {
  items: CustomerSummary[];
  detailState?: string;
}) {
  const columns = [
    { id: "companyName", label: "企業名", width: "38%", minWidth: 240, align: "start" as const, isRowHeader: true },
    { id: "contactName", label: "担当者", width: "22%", minWidth: 160, align: "start" as const },
    { id: "lastContactedAt", label: "最終対応日", width: "22%", minWidth: 160, align: "end" as const },
    { id: "status", label: "ステータス", width: "18%", minWidth: 128, align: "start" as const },
  ];

  return (
    <>
      <div className="collection-table-wrap">
        <Table.Root variant="primary" aria-label="顧客一覧" className="collection-table">
          <Table.ScrollContainer>
            <Table.Content>
              <Table.Header columns={columns}>
                {(column) => (
                  <Table.Column
                    key={column.id}
                    id={column.id}
                    isRowHeader={column.isRowHeader}
                    style={{ width: column.width, minWidth: column.minWidth, textAlign: column.align }}
                  >
                    {column.label}
                  </Table.Column>
                )}
              </Table.Header>
              <Table.Body items={items}>
                {(customer) => (
                  <Table.Row id={customer.id}>
                    <Table.Cell>
                      <Link href={getCompanyHref(customer.id, detailState)} className="table-link">
                        {customer.companyName}
                      </Link>
                    </Table.Cell>
                    <Table.Cell>{customer.contactName}</Table.Cell>
                    <Table.Cell className="table-cell--numeric">{customer.lastContactedAt}</Table.Cell>
                    <Table.Cell>
                      <Chip.Root variant={getStatusVariant(customer.status)}>
                        <Chip.Label>{customer.status}</Chip.Label>
                      </Chip.Root>
                    </Table.Cell>
                  </Table.Row>
                )}
              </Table.Body>
            </Table.Content>
          </Table.ScrollContainer>
        </Table.Root>
      </div>

      <div className="collection-list-mobile" aria-label="顧客一覧モバイル">
        {items.map((customer) => (
          <Card.Root key={customer.id}>
            <Card.Header>
              <Card.Title>
                <Link href={getCompanyHref(customer.id, detailState)} className="table-link">
                  {customer.companyName}
                </Link>
              </Card.Title>
              <Card.Description>{customer.contactName}</Card.Description>
            </Card.Header>
            <Card.Content className="collection-list-mobile__content">
              <div className="collection-list-mobile__meta">
                <span>最終対応日</span>
                <span className="numeric-text">{customer.lastContactedAt}</span>
              </div>
              <div>
                <Chip.Root variant={getStatusVariant(customer.status)}>
                  <Chip.Label>{customer.status}</Chip.Label>
                </Chip.Root>
              </div>
            </Card.Content>
          </Card.Root>
        ))}
      </div>
    </>
  );
}

function CustomerListPage({
  dataVersion,
}: {
  dataVersion: number;
}) {
  const location = useLocation();
  const listState = new URLSearchParams(location.search).get("state");
  const detailState = listState && DETAIL_STATE_NAMES.has(listState as DetailDemoState) ? listState : undefined;
  const [searchValue, setSearchValue] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [items, setItems] = useState<CustomerSummary[]>([]);

  useEffect(() => {
    setIsLoading(true);

    const timerId = window.setTimeout(() => {
      const nextItems = listState === "empty" ? [] : listCustomerSummaries();
      setItems(nextItems);
      setIsLoading(false);
    }, LIST_DELAY_MS);

    return () => window.clearTimeout(timerId);
  }, [dataVersion, listState]);

  const filteredItems = items.filter((customer) => customer.companyName.includes(searchValue.trim()));

  return (
    <main className="page-shell page-shell--stack">
      <div className="page-heading">
        <div className="page-heading__copy">
          <h1>顧客一覧</h1>
          <p>企業名で顧客を探し、選択した会社の詳細画面で基本情報と対応状況を確認します。</p>
        </div>
      </div>

      <section className="collection-region" aria-label="顧客一覧セクション">
        <div className="collection-toolbar">
          <SearchField.Root
            aria-label="企業名で検索"
            className="search-field"
            value={searchValue}
            onChange={setSearchValue}
          >
            <SearchField.Group>
              <SearchField.SearchIcon />
              <SearchField.Input placeholder="企業名で検索" />
              <SearchField.ClearButton aria-label="検索条件をクリア" />
            </SearchField.Group>
          </SearchField.Root>
        </div>

        {isLoading ? (
