.page-shell {
  width: min(100% - 32px, var(--dh-content-max));
  margin: 0 auto;
}

.page-shell--stack {
  padding: var(--dh-space-8) 0 var(--dh-space-12);
}

.page-heading {
  display: flex;
  gap: var(--dh-space-6);
  justify-content: space-between;
  align-items: flex-start;
}

.page-heading__copy {
  max-width: var(--dh-reading-width);
}

.page-heading__copy h1 {
  margin: 0;
  font-size: var(--dh-type-title);
  font-weight: 650;
  line-height: var(--dh-type-line-height-heading);
  text-wrap: balance;
}

.page-heading__copy p {
  margin: var(--dh-space-3) 0 0;
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
  line-height: var(--dh-type-line-height-body);
  text-wrap: pretty;
}

.page-heading__status {
  margin-top: var(--dh-space-3);
}

.page-heading__action {
  flex-shrink: 0;
}

.collection-region {
  display: grid;
  gap: var(--dh-space-3);
  margin-top: var(--dh-space-6);
}

.collection-toolbar {
  width: 100%;
  display: flex;
  justify-content: flex-end;
}

.search-field {
  width: 16rem;
}

.collection-table-wrap {
  display: block;
}

.collection-table {
  width: 100%;
}

.table-link {
  display: inline-flex;
  justify-content: flex-start;
  white-space: normal;
  text-align: left;
}

.table-cell--numeric,
.numeric-text {
  font-variant-numeric: tabular-nums;
}

.collection-list-mobile {
  display: none;
  gap: var(--dh-space-4);
}

.collection-list-mobile__content {
  display: grid;
  gap: var(--dh-space-3);
}

.collection-list-mobile__link {
  width: 100%;
  justify-content: center;
}

.collection-list-mobile__meta {
  display: flex;
  justify-content: space-between;
  gap: var(--dh-space-3);
  align-items: center;
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
  line-height: var(--dh-type-line-height-body);
}

.detail-page__heading {
  display: grid;
  gap: var(--dh-space-4);
  margin-bottom: var(--dh-space-8);
}

.detail-grid {
  display: grid;
  gap: var(--dh-space-6);
}

.detail-content {
  display: grid;
  gap: var(--dh-space-4);
}

.drawer-form {
  display: grid;
  gap: var(--dh-space-6);
}

@media (max-width: 767px) {
  .page-shell {
    width: min(100% - 24px, var(--dh-content-max));
  }

  .page-shell--stack {
    padding: var(--dh-space-6) 0 var(--dh-space-8);
  }

  .page-heading {
    flex-direction: column;
  }

  .page-heading__action {
    width: 100%;
  }

  .page-heading__action .button {
    width: 100%;
  }

  .collection-table-wrap {
    display: none;
  }

  .collection-list-mobile {
    display: grid;
  }

  .collection-toolbar {
    width: 100%;
  }

  .search-field {
    width: 100%;
  }
}

