@import "tailwindcss";
@import "@heroui/styles";
@import "../design/component-theme.css";
@import "../design/layout.css";

:root {
  color: var(--dh-text);
  background: var(--dh-background);
  font-family:
    "Hiragino Sans",
    "Hiragino Kaku Gothic ProN",
    "Yu Gothic UI",
    "Yu Gothic",
    system-ui,
    sans-serif;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--dh-background);
  color: var(--dh-text);
  font-size: var(--dh-type-body);
  line-height: var(--dh-type-line-height-body);
}

a {
  color: inherit;
}

.app-header {
  border-bottom: 1px solid var(--dh-border);
  background: color-mix(in oklch, var(--dh-surface) 92%, var(--dh-accent-soft));
}

.app-header__inner {
  padding-block: var(--dh-space-4);
}

.app-header__eyebrow {
  margin: 0 0 var(--dh-space-1);
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.back-link {
  width: fit-content;
}

.detail-actions {
  display: flex;
  gap: var(--dh-space-2);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.drawer-description {
  margin: 0;
  color: var(--dh-text-muted);
}

.detail-list {
  margin: 0;
  display: grid;
  gap: var(--dh-space-4);
}

.detail-row {
  display: grid;
  gap: var(--dh-space-1);
}

.detail-row dt {
  color: var(--dh-text-muted);
  font-size: var(--dh-type-small);
}

.detail-row dd {
  margin: 0;
  white-space: pre-wrap;
}

.empty-state {
  background: var(--dh-surface);
}

.alert-dialog__body {
  display: grid;
  gap: var(--dh-space-4);
}

@media (max-width: 767px) {
  .detail-actions {
    width: 100%;
    flex-direction: column;
  }

  .detail-actions .button {
    width: 100%;
  }
}

